207	        }
208	        if (claim.getStatus() != ClaimStatus.SETTLED) {
209	            throw new ClaimResettleException("Only a SETTLED claim can be re-settled.");
210	        }
211	        Rollup.Snapshot before = rollup.take(sheetId);
212	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
213	                .orElseThrow(PersonNotFoundException::new);
214	        BigDecimal old = claim.getSettledDue();
215	        BigDecimal figure = liveDue(claim, person);
216	        BigDecimal due = figure == null || claim.isCorrection() ? figure
217	                : figure.add(sheetRows.findById(sheetId).orElseThrow(SheetNotFoundException::new)
218	                        .lateCharge(figure, claim.getDueBy(), claim.getDate()));
219	        claim.setSettledDue(due);
220	        logStatus(claim, person, user);
221	        Claim updated = claims.saveAndFlush(claim);
222	        audit("CLAIM_RESETTLED", updated, person, user, updated.getNumber(),
223	                " old=" + show(old) + " new=" + show(due));
224	        rollup.recordChanges(sheetId, user, before);
225	        return updated;
226	    }
227	
228	    /** Reject a PENDING claim with a reason: it goes back to OPEN, bound again by its person's last
229	     *  statement if that statement included it. Refused unless the claim is PENDING, the user is a
230	     *  steward and a reason is given. */
231	    @Transactional
232	    public Claim reject(String sheetId, String user, long claimId, String reason) {
233	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
234	        refuseClosed(sheetId, claim.getDate());
235	        if (claim.getStatus() != ClaimStatus.PENDING) {
236	            throw new ClaimStatusException(claim.getStatus(), ClaimStatus.OPEN);
237	        }
238	        if (!roles.isSteward(sheetId, user)) {
239	            throw new ClaimApprovalException("Only a steward can reject a claim.");
240	        }
241	        if (reason.isEmpty()) {
242	            throw new ClaimApprovalException("Give a reason to reject the claim.");
243	        }
244	        Rollup.Snapshot before = rollup.take(sheetId);
245	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
246	                .orElseThrow(PersonNotFoundException::new);
247	        claim.setStatus(ClaimStatus.OPEN);
248	        logStatus(claim, person, user);
249	        Claim updated = claims.saveAndFlush(claim);
250	        audit("CLAIM_REJECTED", updated, person, user, updated.getNumber(), " reason=" + reason);
251	        rollup.recordChanges(sheetId, user, before);
252	        return updated;
253	    }
254	
255	    /** Move a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number and date,
256	     *  loses any figure a statement bound it to (live again until its new person's next statement), and is
257	     *  listed as its new person's newest claim. Refused unless the user is a steward, and for a settled or
258	     *  voided claim, a claim in a closed period, the claim's own person, or a person retired on its date. */
259	    @Transactional
260	    public Claim reassign(String sheetId, String user, long claimId, long toPersonId) {
261	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
262	        refuseClosed(sheetId, claim.getDate());
263	        if (!roles.isSteward(sheetId, user)) {
264	            throw new ClaimReassignException("Only a steward can reassign a claim.");
265	        }
266	        if (!claim.getStatus().canMove()) {
267	            throw new ClaimReassignException("A " + claim.getStatus() + " claim cannot be reassigned.");
268	        }
269	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
270	                .orElseThrow(PersonNotFoundException::new);
271	        Person to = people.findByIdAndSheetId(toPersonId, sheetId).orElseThrow(PersonNotFoundException::new);
272	        if (from.getId().equals(to.getId())) {
273	            throw new ClaimReassignException("The claim is already " + to.getName() + "'s.");
274	        }
275	        refuseRetired(to, claim.getDate());
276	        Rollup.Snapshot before = rollup.take(sheetId);
277	        claim.setPersonId(to.getId());
278	        claim.setStated(false, null);
279	        claim.setListOrder(claims.maxListOrder(sheetId) + 1);
280	        Claim updated = claims.saveAndFlush(claim);
281	        audit("CLAIM_REASSIGNED", updated, to, user, updated.getNumber(),
282	                " from=" + from.getName() + " to=" + to.getName());
283	        rollup.recordChanges(sheetId, user, before);
284	        return updated;
285	    }
286	
287	    /** What a bulk open did: how many it opened and refused, and the claims it opened. */
288	    public record BulkOpened(int opened, int refused, List<Claim> claims) {
289	    }
290	
291	    /** Open the chosen claims together, numbering them in list order (people in the order they were added,
292	     *  each person's claims newest first); a claim that cannot be opened is left as it is and counted as
293	     *  refused, as is one not on the sheet. */
294	    @Transactional
295	    public BulkOpened bulkOpen(String sheetId, String user, Collection<Long> claimIds) {
296	        Set<Long> chosen = new HashSet<>(claimIds);
297	        List<Claim> opened = new ArrayList<>();
298	        for (Claim claim : inListOrder(sheetId, chosen)) {
299	            try {
300	                opened.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.OPEN));
301	            } catch (ClaimStatusException | PeriodClosedException | ClaimNotFoundException e) {
302	                // refused: left as it is
303	            }
304	        }
305	        return new BulkOpened(opened.size(), chosen.size() - opened.size(), opened);
306	    }
307	
308	    /** What a bulk settle did: how many it settled (PENDING included) and refused, and the claims it changed. */
309	    public record BulkSettled(int settled, int refused, List<Claim> claims) {
310	    }
311	
312	    /** Settle the chosen claims together in list order (people in the order they were added, each person's
313	     *  claims newest first), each as a single settle by the user would: one a clerk puts PENDING counts as
314	     *  settled, and one that cannot be settled is left as it is and counted as refused, as is one not on
315	     *  the sheet. */
316	    @Transactional
317	    public BulkSettled bulkSettle(String sheetId, String user, Collection<Long> claimIds) {
318	        Set<Long> chosen = new HashSet<>(claimIds);
319	        List<Claim> settled = new ArrayList<>();
320	        for (Claim claim : inListOrder(sheetId, chosen)) {
321	            try {
322	                settled.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.SETTLED));
323	            } catch (ClaimStatusException | ClaimSettlerException | PeriodClosedException
324	                    | ClaimNotFoundException e) {
325	                // refused: left as it is
326	            }
327	        }
328	        return new BulkSettled(settled.size(), chosen.size() - settled.size(), settled);
329	    }
330	
331	    /** The sheet's chosen claims in list order: people in the order they were added, each person's claims
332	     *  newest first. */
333	    private List<Claim> inListOrder(String sheetId, Set<Long> chosen) {
334	        Map<Long, Integer> personOrder = new HashMap<>();
335	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
336	            personOrder.put(person.getId(), personOrder.size());
337	        }
338	        return claims.findBySheetIdOrderByListOrderDesc(sheetId).stream()
339	                .filter(c -> chosen.contains(c.getId()))
340	                .sorted(Comparator.comparing((Claim c) -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE)))
341	                .toList();
342	    }
343	
344	    /** A person, their statements in the order taken, and their claims newest first. */
345	    public record Stated(Person person, List<Statement> statements, List<Claim> claims) {
346	    }
347	
348	    /** Take a person's statement: record their due-total now (late charges included) and how many claims
349	     *  count, and bind each claim that counts to the figure it has now, under its late charge (the charge is
350	     *  never bound: it keeps following the sheet's today; a PENDING claim is bound only once it is back to
351	     *  OPEN); a claim that does not count, or is OPEN or PENDING and dated within one of its person's holds, is
352	     *  left unbound. */
353	    @Transactional
354	    public Stated statement(String sheetId, String user, long personId) {
355	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
356	        LocalDate today = sheets.today(sheetId);
357	        List<Claim> theirs = claims.findForUpdateBySheetIdAndPersonIdOrderByListOrderDesc(sheetId, personId);
358	        Rollup.Snapshot before = rollup.take(sheetId);
359	        BigDecimal total = BigDecimal.ZERO.setScale(2);
360	        boolean figure = false;
361	        int counted = 0;
362	        for (Claim claim : theirs) {
363	            if (!claim.getStatus().counts() || (claim.getStatus().isOpen() && person.heldOn(claim.getDate()))) {
364	                claim.setStated(false, null);
365	                continue;
366	            }
367	            BigDecimal due = due(claim, person);
368	            if (due != null) {
369	                total = total.add(charged(claim, due));
370	                figure = true;
371	            }
372	            claim.setStated(true, due);
373	            counted++;
374	        }
375	        boolean rated = rates.findInForce(sheetId, person.gradeOn(today), today).isPresent();
376	        BigDecimal summed = total;
377	        BigDecimal dueTotal = rated || figure
378	                ? sheetRows.findById(sheetId).map(s -> s.capped(summed)).orElse(summed) : null;
379	        claims.saveAllAndFlush(theirs);
380	        statements.saveAndFlush(new Statement(sheetId, personId, today, dueTotal, counted));
381	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
382	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted);
383	        rollup.recordChanges(sheetId, user, before);
384	        return new Stated(person, statements.findByPersonIdOrderByIdAsc(personId), theirs);
385	    }
386	
387	    /** Refuse a change to a claim dated inside a closed period. Locks the sheet first, so a period being
388	     *  closed at the same moment is seen. */
389	    private void refuseClosed(String sheetId, LocalDate date) {
390	        sheetRows.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
391	        if (periods.closedOn(sheetId, date)) {
392	            throw new PeriodClosedException();
393	        }
394	    }
395	
396	    /** Whether a clerk is settling a due above the sheet's clerk limit; a steward settles anything, and a
397	     *  due of n/a, or a sheet with no limit, is within it. */
398	    private boolean overLimit(String sheetId, String user, BigDecimal due) {
399	        BigDecimal limit = sheetRows.findById(sheetId).orElseThrow(SheetNotFoundException::new).getClerkLimit();
400	        return limit != null && due != null && due.compareTo(limit) > 0 && !roles.isSteward(sheetId, user);
401	    }
402	
403	    /** Refuse a negative amount that does not name a SETTLED claim of the person by number, and a claim of
404	     *  0.00 or more that names one. */
405	    private void refuseCorrection(String sheetId, long personId, BigDecimal amount, String corrects) {
406	        if (amount.signum() >= 0) {
407	            if (corrects != null) {
408	                throw new ClaimCorrectionException("Only a negative amount corrects a claim.");
409	            }
410	            return;
411	        }
412	        if (corrects == null) {
413	            throw new ClaimCorrectionException(
414	                    "A negative amount is a correction: name the number of the settled claim it corrects.");
415	        }
416	        if (!claims.existsBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED)) {
417	            throw new ClaimCorrectionException("A correction must name a settled claim of the same person.");
418	        }
419	    }
420	
421	    /** Refuse a claim dated after its person's retirement date. */
422	    private static void refuseRetired(Person person, LocalDate date) {
423	        if (person.retiredOn(date)) {
424	            throw new PersonRetiredException();
425	        }
426	    }
427	
428	    /** A claim's figure: the due fixed when settled, else the one its last statement bound (not while
429	     *  PENDING), else its live due; none when that is n/a. */
430	    private BigDecimal due(Claim claim, Person person) {
431	        if (claim.getSettledDue() != null) {
432	            return claim.getSettledDue();
433	        }
434	        return claim.isBound() ? claim.getStatedDue() : liveDue(claim, person);
435	    }
436	
437	    /** Log the status a claim has just taken: by the user, on the sheet's today, with its due as the
438	     *  screen shows it now. */
439	    private void logStatus(Claim claim, Person person, String user) {
440	        claim.logStatus(user, sheets.today(claim.getSheetId()), shownDue(claim, person));
441	    }
442	
443	    /** A claim's due as the screen shows it: fixed when settled, else its figure (bound or live) with its
444	     *  late charge on top; none when that is n/a. */
445	    private BigDecimal shownDue(Claim claim, Person person) {
446	        if (claim.getSettledDue() != null) {
447	            return claim.getSettledDue();
448	        }
449	        BigDecimal figure = due(claim, person);
450	        return figure == null ? null : charged(claim, figure);
451	    }
452	
453	    /** A claim's figure with its late charge on the sheet's today on top while it is OPEN or PENDING. */
454	    private BigDecimal charged(Claim claim, BigDecimal figure) {
455	        return Rollup.charged(sheetRows.findById(claim.getSheetId()), claim, figure);
456	    }
457	
458	    /** The claim's amount at the rate in force on its date of its person's grade in force then, at least the sheet's floor in force then
459	     *  (a correction has none); none when no rate applies. */
460	    private BigDecimal liveDue(Claim claim, Person person) {
461	        Sheet sheet = sheetRows.findById(claim.getSheetId()).orElseThrow(SheetNotFoundException::new);
462	        RoundingMode rounding = sheet.rounding(roundingDate(claim));
463	        return rates.findInForce(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate())
464	                .map(rate -> claim.isCorrection() ? due(claim.getAmount(), rate, rounding)
465	                        : sheet.floored(due(claim.getAmount(), rate, rounding), claim.getDate()))
466	                .orElse(null);
467	    }
468	
469	    /** The date a claim's figures round by: its own, or for a correction the date of the claim it corrects. */
470	    private LocalDate roundingDate(Claim claim) {
471	        if (!claim.isCorrection()) {
472	            return claim.getDate();
473	        }
474	        return claims.findBySheetIdAndPersonIdAndNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects())
475	                .map(Claim::getDate).orElse(claim.getDate());
476	    }
477	
478	    /** An amount times a rate, divided by 100, rounded to cents. */
479	    private static BigDecimal due(BigDecimal amount, Rate rate, RoundingMode rounding) {
480	        return amount.multiply(rate.getRate()).movePointLeft(2).setScale(2, rounding);
481	    }
482	
483	    /** The due a settled claim was fixed at, as its audit line ends: n/a when it has none. */
484	    private static String dueField(Claim claim) {
485	        return " due=" + (claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString());
486	    }
487	
488	    /** A due as an audit line shows it: n/a when there is none. */
489	    private static String show(BigDecimal due) {
490	        return due == null ? "n/a" : due.toPlainString();
491	    }
492	
493	    /** The amount as the screen shows it (two decimals), the date YYYY-MM-DD. */
494	    private void audit(String event, Claim claim, Person person, String user) {
495	        audit(event, claim, person, user, claim.getNumber(), "");
496	    }
497	
498	    /** A claim with a number (a voided claim keeps its own) follows its date with number=, then any extra fields. */
499	    private void audit(String event, Claim claim, Person person, String user, String number, String extra) {
500	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user
501	                + " person=" + person.getName() + " amount=" + claim.getAmount().toPlainString()
502	                + " date=" + claim.getDate() + (number != null ? " number=" + number : "") + extra);
503	    }
504	}
