30	/** The people's claims on a sheet. The signed-in user's name comes in the X-User header. */
31	@RestController
32	@Validated
33	@RequestMapping("/api/sheets/{sheetId}")
34	public class ClaimController {
35	
36	    /** A claim as the screen shows it: the amount with two decimals, the date YYYY-MM-DD, no number unless opened,
37	     *  the due fixed when it was settled (none while its due is live)
38	     *  who opened it (none while a draft), whether its person's last statement bound it and the figure
39	     *  it bound (none while unbound, or when that was n/a), and the number a correction corrects (none
40	     *  otherwise), and its status log, oldest first. */
41	    public record ClaimView(long id, long personId, String amount, String date, String note,
42	            ClaimStatus status, String number, String settledDue, String openedBy, boolean stated,
43	            String statedDue, String corrects, String dueBy, List<StatusLine> statusLog) {
44	
45	        static ClaimView of(Claim claim) {
46	            return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
47	                    claim.getDate().toString(), claim.getNote(), claim.getStatus(), claim.getNumber(),
48	                    claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
49	                    claim.getOpenedBy(), claim.isStated(),
50	                    claim.getStatedDue() == null ? null : claim.getStatedDue().toPlainString(),
51	                    claim.getCorrects(), claim.getDueBy().toString(),
52	                    claim.getStatusLog().stream().map(StatusLine::of).toList());
53	        }
54	    }
55	
56	    /** A line of a claim's status log: the status, who changed it, the sheet's today then (YYYY-MM-DD), and
57	     *  the due it had then, two decimals (none when n/a). */
58	    public record StatusLine(ClaimStatus status, String by, String on, String due) {
59	
60	        static StatusLine of(StatusChange change) {
61	            return new StatusLine(change.getStatus(), change.getBy(), change.getOn().toString(),
62	                    change.getDue() == null ? null : change.getDue().toPlainString());
63	        }
64	    }
65	
66	    /** A claim's fields; a missing date takes the sheet's today, a missing note is empty. A negative
67	     *  amount (a correction) names the number of the claim it corrects. */
68	    public record ClaimRequest(
69	            @NotNull @Digits(integer = 13, fraction = 2) BigDecimal amount,
70	            LocalDate date,
71	            @Size(max = 1000) String note,
72	            @Size(max = 220) String corrects) {
73	
74	        String noteOrEmpty() {
75	            return note == null ? "" : note.trim();
76	        }
77	
78	        /** The number a correction names, trimmed; none when blank. */
79	        String correctsOrNone() {
80	            return corrects == null || corrects.isBlank() ? null : corrects.trim();
81	        }
82	    }
83	
84	    /** The quick-add bar's name and amount. */
85	    public record QuickAddRequest(
86	            @NotBlank @Size(max = 200) String name,
87	            @NotNull @DecimalMin("0.00") @Digits(integer = 13, fraction = 2) BigDecimal amount) {
88	    }
89	
90	    /** The person a quick-add claimed for, whether it added them, and the claim. */
91	    public record QuickAddView(PersonView person, boolean personAdded, ClaimView claim) {
92	    }
93	
94	    /** The paste box's lines of name,amount,date,note. */
95	    public record PasteRequest(@NotNull @Size(max = 1000000) String text) {
96	    }
97	
98	    /** How many a paste added, and the claims it added, in the order of their lines. */
99	    public record PasteView(int added, List<ClaimView> claims) {
100	    }
101	
102	    private final ClaimService service;
103	    private final QuickAddService quickAdd;
104	    private final PasteService paste;
105	    private final PersonService people;
106	
107	    public ClaimController(ClaimService service, QuickAddService quickAdd, PasteService paste, PersonService people) {
108	        this.service = service;
109	        this.quickAdd = quickAdd;
110	        this.paste = paste;
111	        this.people = people;
112	    }
113	
114	    /** The sheet's claims, newest first. */
115	    @GetMapping("/claims")
116	    public List<ClaimView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId,
117	            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user) {
118	        return service.list(sheetId.trim()).stream().map(ClaimView::of).toList();
119	    }
120	
121	    /** Add a claim for a person. */
122	    @PostMapping("/people/{personId}/claims")
123	    public ClaimView add(@PathVariable @NotBlank @Size(max = 200) String sheetId,
124	            @PathVariable long personId,
125	            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
126	            @RequestBody @Valid ClaimRequest request) {
127	        return ClaimView.of(service.add(sheetId.trim(), user.trim(), personId, request.amount(), request.date(),
128	                request.noteOrEmpty(), request.correctsOrNone()));
129	    }
130	
131	    /** Add a DRAFT claim dated the sheet's today for the person with the name, adding them first when
132	     *  the sheet has no one by it. */
133	    @PostMapping("/quick-claims")
134	    public QuickAddView quickAdd(@PathVariable @NotBlank @Size(max = 200) String sheetId,
135	            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
136	            @RequestBody @Valid QuickAddRequest request) {
137	        QuickAddService.Added added = quickAdd.add(sheetId.trim(), user.trim(), request.name(), request.amount());
138	        return new QuickAddView(PersonView.of(added.person(), people.today(sheetId.trim()), people.statementsOf(added.person().getId()),
139	                people.patronsOf(added.person().getId())),
140	                added.personAdded(), ClaimView.of(added.claim()));
141	    }
142	
143	    /** Add a DRAFT claim for each pasted line, in order; one refused line refuses them all. */
